/* Golden Braid / AIDM / B1 supplementary S26 Berserker acceptance cases
FILE: MonsterTestCase_Mentzer_Basic_Berserker_Insert.sql
TARGET: PEQUOD / DnD (SQL Server 2016+)
SCENARIOS: T001 wandering; T002 scripted Room54 guardians.
DATE: 2026-11-22. All cases Specified only, no execution, UAT or status promotion.
Combat and Encounter are separate TestPhase records; no Encounter engine invented.
*/
USE [DnD];
GO
IF OBJECT_ID(N'Test.MonsterTestCase',N'U') IS NULL THROW 57303,'Test.MonsterTestCase missing',1;
IF NOT EXISTS(SELECT 1 FROM [Test].[MonsterTestScenario] WHERE [ScenarioCode]=N'BERSERKER-T001')
 OR NOT EXISTS(SELECT 1 FROM [Test].[MonsterTestScenario] WHERE [ScenarioCode]=N'BERSERKER-T002')
 THROW 57304,'Missing Berserker scenario(s): deploy scenario insert first',1;
GO
SET XACT_ABORT ON;
GO
BEGIN TRY
 BEGIN TRAN;
 DECLARE @Seed TABLE
 ([ScenarioCode] NVARCHAR(80) NOT NULL,[TestCaseCode] NVARCHAR(80) NOT NULL,[SequenceNo] INT NOT NULL,
 [TestName] NVARCHAR(180) NOT NULL,[TestPhase] NVARCHAR(40) NOT NULL,[TestStatus] NVARCHAR(20) NOT NULL,
 [TestRevision] INT NOT NULL,[GivenText] NVARCHAR(MAX) NOT NULL,[ExpectedText] NVARCHAR(MAX) NOT NULL,
 [DiceFixtureJson] NVARCHAR(MAX) NULL,[AdditionalDataJson] NVARCHAR(MAX) NULL,
 [LinkedStoryRef] NVARCHAR(80) NULL,[AutomatedTestRef] NVARCHAR(500) NULL,[Notes] NVARCHAR(MAX) NULL);
 INSERT INTO @Seed ([ScenarioCode],[TestCaseCode],[SequenceNo],[TestName],[TestPhase],[TestStatus],[TestRevision],[GivenText],[ExpectedText],[DiceFixtureJson],[AdditionalDataJson],[LinkedStoryRef],[AutomatedTestRef],[Notes]) VALUES
  (N'BERSERKER-T001',N'BER-C01',1,N'Conditional +2 Hit against human',N'COMBAT',N'Specified',1,N'BER-T001-1 attacks a known human in melee; natural d20=8.',N'Effective Hit roll is 10 before other validated modifiers; +2 applies to Hit, not damage.',N'{"attack_d20":8}',N'{"target_type":"human","modifier_to_hit":2,"modifier_to_damage":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C02',2,N'Conditional +2 Hit against kobold',N'COMBAT',N'Specified',1,N'BER-T001-1 attacks a verified kobold; natural d20=12.',N'Effective Hit roll is 14 from humanoid ferocity. Do not add +2 damage.',N'{"attack_d20":12}',N'{"target_type":"kobold","effective_hit_roll":14,"weapon_damage_bonus":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C03',3,N'No +2 against non-humanoid',N'COMBAT',N'Specified',1,N'BER-T001-1 attacks an identified Giant Rat; natural d20=12.',N'Do not add the Berserker +2 conditional Hit modifier; use 12 before other normal modifiers.',N'{"attack_d20":12}',N'{"target_type":"giant_rat","berserker_to_hit_modifier":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C04',4,N'Sword variable weapon damage',N'COMBAT',N'Specified',1,N'BER-T001-1 makes a verified successful sword attack with Variable Weapon Damage enabled.',N'Apply sword 1d8=6 only; do not add +2 to damage.',N'{"confirmed_hit":true,"sword_d8":6}',N'{"damage":6,"bonus_damage":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C05',5,N'War hammer standard weapon damage',N'COMBAT',N'Specified',1,N'BER-T001-2 scores a legal melee hit with a war hammer, standard weapon damage.',N'Apply normal 1d6=5 to intended target; no Berserker-specific weapon bonus.',N'{"confirmed_hit":true,"standard_damage_d6":5}',N'{"damage":5}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C06',6,N'Morale 12 suppresses checks',N'COMBAT',N'Specified',1,N'An ordinary morale-check trigger occurs during an established fight.',N'No morale dice are rolled for Berserkers at Morale 12; they continue fighting while able.',NULL,N'{"morale":12,"morale_rolls_required":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C07',7,N'No voluntary surrender after fighting starts',N'COMBAT',N'Specified',1,N'An able Berserker is offered surrender or withdrawal during established combat.',N'The Berserker does not voluntarily surrender, retreat or seek prisoners; no forced morale check.',NULL,N'{"surrender":false,"voluntary_retreat":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C08',8,N'Natural 1 one ally in melee reach',N'COMBAT',N'Specified',1,N'BER-T001-1 makes melee sword attack, natural d20=1; only BER-T001-2 is an active ally within actual reach; Variable Weapon Damage is active; sword damage d8=5.',N'Original enemy takes 0; BER-T001-2 is automatically hit for exactly 5 HP without a second d20.',N'{"attack_d20":1,"sword_damage_d8":5,"variable_weapon_damage_enabled":true}',N'{"ally_ids_in_reach":["BER-T001-2"],"damaged_actor":"BER-T001-2","damage":5,"second_hit_roll":false,"original_target_damage":0,"house_rule":"wild_swing"}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C09',9,N'Natural 1 no eligible ally',N'COMBAT',N'Specified',1,N'BER-T001-1 swings at enemy; d20=1, BER-T001-2 out of melee reach.',N'Ordinary miss, zero damage to every actor; do not pick out-of-reach ally.',N'{"attack_d20":1}',N'{"ally_ids_in_reach":[],"damage":0,"wild_swing_hit":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C10',10,N'Natural 1 selects uniformly among allies',N'COMBAT',N'Specified',1,N'A separate synthetic branch adds two extra allies within reach for selection, leaving the canonical two-Berserker fixture unchanged. Three eligible ally IDs ordered A/B/C, uniformly sampled selection index=2 (1 based).',N'Exactly second eligible ally B takes normal weapon damage 4; all three have equal probability and no additional Hit roll.',N'{"attack_d20":1,"ally_uniform_index_1_based":2,"sword_damage_d8":4,"variable_weapon_damage_enabled":true}',N'{"eligible_allies":["A","B","C"],"selection_rule":"uniform","selected":"B","damage":4,"fixture_variation_only":true}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C11',11,N'Natural 1 overrides humanoid +2 Hit',N'COMBAT',N'Specified',1,N'Berserker swings melee at a human d20=1; one ally in reach.',N'Natural 1 misses intended human despite +2; eligible ally takes one normal weapon hit.',N'{"attack_d20":1,"sword_damage_d8":3,"variable_weapon_damage_enabled":true}',N'{"target_type":"human","potential_to_hit_modifier":2,"actual_target_hit":false,"selected_ally_damage":3}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C12',12,N'Natural 2 does not trigger Wild Swing',N'COMBAT',N'Specified',1,N'Berserker makes sword melee attack natural d20=2 with an ally in reach.',N'Resolve ordinary Hit procedure with relevant modifiers; no forced friendly-fire hit.',N'{"attack_d20":2}',N'{"wild_swing":false,"normal_hit_resolution":true}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C13',13,N'Natural 1 ranged does not use Wild Swing',N'COMBAT',N'Specified',1,N'Separate legal scenario variant equips an approved missile weapon and makes ranged attack natural 1.',N'Normal ranged miss; no random allied melee hit despite ally in reach.',N'{"attack_d20":1}',N'{"attack_kind":"missile","wild_swing":false,"damage":0,"fixture_variation_only":true}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C14',14,N'Only active reachable allies eligible',N'COMBAT',N'Specified',1,N'One allied actor is defeated, a second out of reach and a third active and in reach; wild swing natural 1.',N'Only the active in-reach ally is eligible, not self or defeated/out-of-range allies.',N'{"attack_d20":1,"weapon_damage_d6":4}',N'{"eligible":["active_in_reach"],"excluded":["self","defeated","out_of_reach"],"damage":4,"fixture_variation_only":true}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C15',15,N'Defeated Berserker cannot act',N'COMBAT',N'Specified',1,N'BER-T001-2 is at 4 HP and takes four valid damage before its later attack.',N'At 0 HP it cannot execute a later ordinary attack; no resurrected attack due to morale 12.',N'{"incoming_damage":4}',N'{"starting_hp":4,"ending_hp":0,"late_action_allowed":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C16',16,N'B1 wandering movement override',N'COMBAT',N'Specified',1,N'Combat begins using validated B1 T001 roster with individual movement 90/30.',N'Combat uses 30ft/round for these actors, while reusable Mentzer Berserker species remains 40ft/round.',NULL,N'{"source":"B1 upper wandering table","encounter_round_feet":30,"species_round_feet":40}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-C17',17,N'Audit Wild Swing damage and selection',N'COMBAT',N'Specified',1,N'Natural 1 melee attack and two eligible allies; selected ally and one damage roll provided.',N'Journal raw d20, chosen eligible list, uniform selection, weapon damage, actual ally, no damage to intended target and house-rule provenance; do not run a second hit.',N'{"attack_d20":1,"uniform_choice_1_based":1,"weapon_damage_d8":4,"variable_weapon_damage_enabled":true}',N'{"trace_required":["raw_attack_roll","house_rule","eligible_allies","uniform_selection","damage_roll","actual_victim","zero_damage_original_target"],"fixture_variation_only":true}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T001',N'BER-E01',18,N'B1 wandering group identities and HP',N'ENCOUNTER',N'Specified',1,N'B1 upper wandering entry chooses two Berserkers with listed HP5 and HP4.',N'Create two separate actors 5/4 HP and AC7; no user-rolled replacement of B1 HP.',NULL,N'{"count":2,"hp":[5,4],"source":"B1 upper wandering"}',NULL,NULL,N'Future Encounter Engine specification; not executed.'),
  (N'BERSERKER-T001',N'BER-E02',19,N'Normal pre-combat reaction',N'ENCOUNTER',N'Specified',1,N'Two Berserkers approach the party before any battle has begun.',N'Use normal reaction/DM interpretation; do not automatically initiate fight because they are Berserkers.',NULL,N'{"forced_combat":false,"normal_reaction":true}',NULL,NULL,N'Future Encounter Engine specification; not executed.'),
  (N'BERSERKER-T001',N'BER-E03',20,N'Normal surprise d6 per side',N'ENCOUNTER',N'Specified',1,N'Party d6=5, Berserkers d6=3 when meeting along corridor.',N'Neither surprised; one roll per side; no Berserker automatic ambush.',N'{"party_surprise_d6":5,"berserker_surprise_d6":3}',N'{"surprised_party":false,"surprised_berserkers":false}',NULL,NULL,N'Future Encounter Engine specification; not executed.'),
  (N'BERSERKER-T001',N'BER-E04',21,N'B1 overrides species exploration movement',N'ENCOUNTER',N'Specified',1,N'Upper-level wandering Berserkers are selected using B1 encounter stats.',N'Pass B1 movement 90ft/turn and 30ft/round, NOT base species 120/40; preserve distinction.',NULL,N'{"B1_movement":[90,30],"base_movement":[120,40]}',NULL,NULL,N'Future Encounter Engine specification; not executed.'),
  (N'BERSERKER-T001',N'BER-E05',22,N'Synthetic weapon loadouts explicit',N'ENCOUNTER',N'Specified',1,N'The fixed test fixture selects a sword and a war hammer for the two wandering Berserkers.',N'Keep specified real equipped weapons; do not claim B1 published either loadout.',NULL,N'{"equipment":["sword","war_hammer"],"equipment_source":"synthetic_fixture"}',NULL,NULL,N'Future Encounter Engine specification; not executed.'),
  (N'BERSERKER-T001',N'BER-E06',23,N'Wandering encounter structured handoff',N'ENCOUNTER',N'Specified',1,N'A normal reaction/decision actually escalates to battle.',N'Supply two actors with HP5/4, AC7, movement90/30, real weapons and established surprise; no reaction algorithm in Combat.',NULL,N'{"actors":["BER-T001-1","BER-T001-2"],"hp":[5,4],"move_round":30,"no_encounter_logic_in_combat":true}',NULL,NULL,N'Future Encounter Engine specification; not executed.'),
  (N'BERSERKER-T001',N'BER-E07',24,N'Before combat withdrawal permitted',N'ENCOUNTER',N'Specified',1,N'The party backs away from the armed Berserkers before either side has attacked.',N'Allow normal interpretation of withdrawal, pursuit or non-hostile response; do not import post-battle never-retreat constraint before combat.',NULL,N'{"fight_started":false,"mandatory_combat":false}',NULL,NULL,N'Future Encounter Engine specification; not executed.'),
  (N'BERSERKER-T002',N'BER2-C01',1,N'Room54 fixed guardian HP and AC',N'COMBAT',N'Specified',1,N'Both B1 Room54 statues have activated and enter combat.',N'Preserve independently fixed 4 HP and AC7 per actor; no automatic 1d8+1 reroll.',NULL,N'{"hp":[4,4],"ac":[7,7],"hp_source":"B1 Room54"}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T002',N'BER2-C02',2,N'Activated guardian uses sword attack',N'COMBAT',N'Specified',1,N'Activated guardian BER-T002-1 has a valid sword hit, standard damage d6=3.',N'One equipped sword attack for 3 normal damage, not extra magical damage.',N'{"confirmed_hit":true,"standard_damage_d6":3}',N'{"damage":3,"additional_magic_damage":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T002',N'BER2-C03',3,N'Statue guardian natural 1 friendly fire',N'COMBAT',N'Specified',1,N'Animated guardians fight as allies in sword melee reach; guardian 1 rolls natural1, guardian2 is active and in reach.',N'Apply approved Wild Swing: intended target misses, guardian2 automatically takes sword damage once; no magic immunity inferred.',N'{"attack_d20":1,"sword_damage_d8":4,"variable_weapon_damage_enabled":true}',N'{"damaged_actor":"BER-T002-2","damage":4,"original_target_damage":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T002',N'BER2-C04',4,N'Guardian +2 Hit versus humanoids',N'COMBAT',N'Specified',1,N'An activated Room54 Berserker attacks a human with natural d20=9.',N'Apply base Berserker +2 to Hit, yielding 11 before other modifiers, unless unmodified d20=1 (separately tested).',N'{"attack_d20":9}',N'{"target_type":"human","effective_hit_roll":11}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T002',N'BER2-C05',5,N'No morale check for guardian',N'COMBAT',N'Specified',1,N'Activated statue guardian remains capable of action and a normal morale checkpoint would otherwise occur.',N'With Berserker morale12, no check and no voluntary surrender/retreat; normal defeat mechanics still apply.',NULL,N'{"morale":12,"check_count":0,"surrender":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat acceptance case, not executed.'),
  (N'BERSERKER-T002',N'BER2-E01',6,N'Two inert statues before trigger',N'ENCOUNTER',N'Specified',1,N'The party enters Room54 and sees two lifelike statues but does not disturb an item of value.',N'Guardians remain inert, no Combat handoff, no automatic hostility roll simply from sight.',NULL,N'{"initial_inert_count":2,"activated":false,"combat_started":false}',NULL,NULL,N'Future Encounter Engine specification; not executed.'),
  (N'BERSERKER-T002',N'BER2-E02',7,N'Valuable touched activates both',N'ENCOUNTER',N'Specified',1,N'A player touches or disturbs a valuable item in B1 Room54.',N'Both statues animate and draw swords; activation event is interpreted by Encounter before Combat.',NULL,N'{"trigger":"valuable_touched","activated_actor_ids":["BER-T002-1","BER-T002-2"]}',NULL,NULL,N'Future Encounter Engine specification; not executed.'),
  (N'BERSERKER-T002',N'BER2-E03',8,N'Mere proximity does not trigger',N'ENCOUNTER',N'Specified',1,N'The party inspects and moves through the room without touching/disturbing anything of value.',N'Do not animate guardians solely on proximity or because the illustration depicts Berserkers.',NULL,N'{"trigger":false,"activated":false}',NULL,NULL,N'Future Encounter Engine specification; not executed.'),
  (N'BERSERKER-T002',N'BER2-E04',9,N'No automatic surprise from animation',N'ENCOUNTER',N'Specified',1,N'Room54 valuable is disturbed and statues animate.',N'Do not assert a surprise roll/result from animation unless the DM legitimately resolves surprise under the scene rules.',NULL,N'{"automatic_surprise":false,"surprise_roll_defined":false}',NULL,NULL,N'Future Encounter Engine specification; not executed.'),
  (N'BERSERKER-T002',N'BER2-E05',10,N'Magical nature adds no inferred immunity',N'ENCOUNTER',N'Specified',1,N'Activated B1 guardians are described as magical berserkers.',N'Do not add immunity to weapons/spells or regeneration solely from descriptive adjective magical.',NULL,N'{"unsourced_immunities":[],"unsourced_bonus_damage":0}',NULL,NULL,N'Future Encounter Engine specification; not executed.'),
  (N'BERSERKER-T002',N'BER2-E06',11,N'Room54 structured handoff on activation',N'ENCOUNTER',N'Specified',1,N'Both treasures guardians are activated by the actual room trigger.',N'Hand off two sword users AC7 HP4/4 and validated positions, no invented surprise, and no treasure carried personally; Combat runs standard algorithm.',NULL,N'{"actors":["BER-T002-1","BER-T002-2"],"hp":[4,4],"ac":7,"weapons":["sword","sword"],"no_encounter_logic_in_combat":true}',NULL,NULL,N'Future Encounter Engine specification; not executed.');
 INSERT INTO [Test].[MonsterTestCase] ([ScenarioCode],[TestCaseCode],[SequenceNo],[TestName],[TestPhase],[TestStatus],[TestRevision],[GivenText],[ExpectedText],[DiceFixtureJson],[AdditionalDataJson],[LinkedStoryRef],[AutomatedTestRef],[Notes])
 SELECT s.[ScenarioCode],s.[TestCaseCode],s.[SequenceNo],s.[TestName],s.[TestPhase],s.[TestStatus],s.[TestRevision],s.[GivenText],s.[ExpectedText],s.[DiceFixtureJson],s.[AdditionalDataJson],s.[LinkedStoryRef],s.[AutomatedTestRef],s.[Notes] FROM @Seed AS s
 WHERE NOT EXISTS(SELECT 1 FROM [Test].[MonsterTestCase] AS t WITH(UPDLOCK,HOLDLOCK)
                  WHERE t.[ScenarioCode]=s.[ScenarioCode] AND t.[TestCaseCode]=s.[TestCaseCode]);
 PRINT CONCAT(N'Inserted new Berserker test definitions: ',@@ROWCOUNT);
 COMMIT;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK;
 THROW;
END CATCH;
GO
SELECT [ScenarioCode],[TestPhase],[TestStatus],COUNT(*) AS [TestCount]
FROM [Test].[MonsterTestCase]
WHERE [ScenarioCode] IN (N'BERSERKER-T001',N'BERSERKER-T002')
GROUP BY [ScenarioCode],[TestPhase],[TestStatus]
ORDER BY [ScenarioCode],[TestPhase];
GO
